"""secretscan.py — regex + entropy secret scanner.

Rules
-----
aws-access-key-id : AKIA followed by 16 uppercase alphanumerics
github-pat        : ghp_ followed by 36 alphanumerics
assignment-secret : 'password'/'secret' assignment with a quoted literal of 8+ chars
high-entropy      : any quoted string token of length >= 20 with Shannon
                    entropy > 4.0 bits/char

Output: path:line:rule:masked-secret   (mask shows only the first 4 chars)

An allowlist file (one literal per line, '#' comments allowed) suppresses
findings whose full secret text matches exactly.
"""

from __future__ import annotations

import argparse
import math
import re
import sys
from pathlib import Path

DEFAULT_ALLOWLIST = ".secrets-allowlist"

# --- Regex rules -------------------------------------------------------------

AWS_KEY_RE = re.compile(r"\b(AKIA[0-9A-Z]{16})\b")
GITHUB_PAT_RE = re.compile(r"\b(ghp_[0-9A-Za-z]{36})\b")

# 'password' or 'secret' (case-insensitive, optional -/_) as a key in an
# assignment or mapping, with a quoted literal of 8+ chars.
ASSIGNMENT_RE = re.compile(
    r"""(?i)\b(?:password|secret)[-_]?\w*\s*[:=]\s*(['"])([^'"]{8,}?)\1"""
)

# Any single- or double-quoted string token (for the entropy rule).
QUOTED_RE = re.compile(r"""(['"])((?:\\.|(?!\1).)+?)\1""")

# --- Entropy rule ------------------------------------------------------------

ENTROPY_MIN_LEN = 20
ENTROPY_THRESHOLD = 4.0


def shannon_entropy(text: str) -> float:
    """Shannon entropy of a string in bits per character."""
    if not text:
        return 0.0
    counts: dict[str, int] = {}
    for ch in text:
        counts[ch] = counts.get(ch, 0) + 1
    total = len(text)
    return -sum(
        (n / total) * math.log2(n / total) for n in counts.values()
    )


def mask(secret: str) -> str:
    """Masked form: only the first 4 characters are shown."""
    tail = "..." if len(secret) > 4 else ""
    return secret[:4] + tail


# --- Scanner -----------------------------------------------------------------

RULE_NAMES = (
    "aws-access-key-id",
    "github-pat",
    "assignment-secret",
    "high-entropy-string",
)


class Finding:
    def __init__(self, path: str, line: int, rule: str, secret: str):
        self.path = path
        self.line = line
        self.rule = rule
        self.secret = secret

    def key(self) -> tuple[str, int, str]:
        return (self.path, self.line, self.rule)

    @property
    def masked(self) -> str:
        return f"{self.path}:{self.line}:{self.rule}:{mask(self.secret)}"

    def __repr__(self) -> str:  # pragma: no cover
        return f"Finding({self.masked!r})"


def load_allowlist(path: Path | None) -> set[str]:
    entries: set[str] = set()
    if path is None or not path.exists():
        return entries
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        entries.add(line)
    return entries


def scan_line(path: str, lineno: int, line: str, allowlist: set[str]) -> list[Finding]:
    findings: list[Finding] = []

    def allowed(secret: str) -> bool:
        if not allowlist:
            return False
        # exact match, or match after stripping surrounding quotes
        stripped = secret.strip("'\"")
        return secret in allowlist or stripped in allowlist

    for m in AWS_KEY_RE.finditer(line):
        if not allowed(m.group(1)):
            findings.append(Finding(path, lineno, "aws-access-key-id", m.group(1)))

    for m in GITHUB_PAT_RE.finditer(line):
        if not allowed(m.group(1)):
            findings.append(Finding(path, lineno, "github-pat", m.group(1)))

    for m in ASSIGNMENT_RE.finditer(line):
        secret = m.group(2)
        if not allowed(secret):
            findings.append(Finding(path, lineno, "assignment-secret", secret))

    for m in QUOTED_RE.finditer(line):
        secret = m.group(2)
        if len(secret) < ENTROPY_MIN_LEN:
            continue
        if shannon_entropy(secret) <= ENTROPY_THRESHOLD:
            continue
        if not allowed(secret):
            findings.append(Finding(path, lineno, "high-entropy-string", secret))

    return findings


def scan_file(path: Path, allowlist: set[str]) -> list[Finding]:
    findings: list[Finding] = []
    try:
        text = path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, OSError):
        return findings  # skip binaries / unreadable files
    rel = str(path)
    for lineno, line in enumerate(text.splitlines(), start=1):
        findings.extend(scan_line(rel, lineno, line, allowlist))
    return findings


def scan(paths: list[Path], allowlist_file: Path | None) -> list[Finding]:
    allowlist = load_allowlist(allowlist_file)
    findings: list[Finding] = []
    files: list[Path] = []
    for p in paths:
        if p.is_dir():
            files.extend(sorted(x for x in p.rglob("*") if x.is_file()))
        else:
            files.append(p)
    for f in files:
        findings.extend(scan_file(f, allowlist))
    return findings


# --- CLI ---------------------------------------------------------------------


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Regex + entropy secret scanner.")
    parser.add_argument("paths", nargs="+", type=Path, help="Files or directories to scan")
    parser.add_argument(
        "--allowlist",
        "-a",
        type=Path,
        default=None,
        help=f"Allowlist file of literals to ignore (default: {DEFAULT_ALLOWLIST} if present)",
    )
    args = parser.parse_args(argv)

    allowlist_file = args.allowlist
    if allowlist_file is None:
        default_path = Path(DEFAULT_ALLOWLIST)
        if default_path.exists():
            allowlist_file = default_path

    findings = scan(args.paths, allowlist_file)
    for f in sorted(findings, key=lambda x: x.key()):
        print(f.masked)
    return 1 if findings else 0


if __name__ == "__main__":
    sys.exit(main())
